import sys

def range_and_brute(left, right):
    res = left
    for i in range(left + 1, right + 1):
        res &= i
        if res == 0:
            break
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    left = int(data[0]); right = int(data[1])
    print(range_and_brute(left, right))

import sys

def range_and_best(left, right):
    while left < right:
        right &= right - 1
    return right

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    left = int(data[0]); right = int(data[1])
    print(range_and_best(left, right))
